SELECT table_name, constraint_name, constraint_type FROM information_schema.table_constraints WHERE constraint_schema = 'library_db1' AND table_name IN ('book_loans','reservations') ORDER BY table_name, constraint_type, constraint_name;
SELECT tc.table_name, tc.constraint_name, cc.check_clause FROM information_schema.table_constraints tc JOIN information_schema.check_constraints cc ON cc.constraint_schema = tc.constraint_schema AND cc.constraint_name = tc.constraint_name WHERE tc.constraint_schema = 'library_db1' AND tc.table_name IN ('book_loans','reservations') AND tc.constraint_type = 'CHECK' ORDER BY tc.table_name, tc.constraint_name;
SELECT table_name, constraint_name, column_name, referenced_table_name, referenced_column_name FROM information_schema.key_column_usage WHERE table_schema = 'library_db1' AND table_name IN ('book_loans','reservations') AND referenced_table_name IS NOT NULL ORDER BY table_name, constraint_name, ordinal_position;
SELECT table_name, column_name, column_type, is_nullable, column_default FROM information_schema.columns WHERE table_schema = 'library_db1' AND table_name = 'book_reviews' AND column_name = 'is_anonymous';